<?php $this->layout('default'); use Moves\Services\CmsAnalytics; use Moves\Support\CmsView as V; $r = CmsAnalytics::report(30); $values = array_values($r['series']); $max = max(1, max($values));
$this->start('actions'); ?><span class="cms-online"><?= (int) $r['online_count'] ?> online agora</span><a class="cms-btn" href="<?= V::e(getenv('APP_URL') ?: '/') ?>" target="_blank" rel="noopener">Ver site</a><?php $this->stop(); ?>
<?= V::kpis([['users', 'Visitantes', number_format($r['visitors'], 0, ',', '.'), 'por dia, nos últimos 30 dias'], ['globe', 'Sessões', number_format($r['sessions'], 0, ',', '.'), 'visitas registradas'], ['eye', 'Visualizações', number_format($r['views'], 0, ',', '.'), $r['sessions'] > 0 ? number_format($r['views'] / $r['sessions'], 1, ',', '') . ' páginas por sessão' : 'sem sessões'], ['chart', 'Evolução', $r['trend'] === null ? '—' : ($r['trend'] > 0 ? '+' : '') . number_format($r['trend'], 1, ',', '') . '%', 'comparação entre metades']]) ?>
<div class="cms-chart-card"><section class="cms-card"><header class="cms-card-head"><div><h2>Visualizações por dia</h2><small>Páginas acessadas nos últimos 30 dias.</small></div></header><div class="cms-chart" role="img" aria-label="Visualizações por dia nos últimos 30 dias. Total <?= (int) $r['views'] ?>."><?php foreach ($r['series'] as $day => $total): ?><div class="cms-bar" title="<?= V::e(date('d/m', strtotime($day))) ?>: <?= (int) $total ?> visualização(ões)"><?php if ($total > 0): ?><b><?= (int) $total ?></b><i style="height:<?= round($total / $max * 100, 1) ?>%"></i><?php endif; ?></div><?php endforeach; ?></div><div class="cms-chart-axis" aria-hidden="true"><?php foreach (array_keys($r['series']) as $i => $day): ?><span><?= $i % 3 === 0 ? V::e(date('d/m', strtotime($day))) : '' ?></span><?php endforeach; ?></div><div class="cms-chart-stats"><div><small>Maior volume</small><strong><?= max($values) ?></strong></div><div><small>Média diária</small><strong><?= number_format(array_sum($values) / count($values), 1, ',', '') ?></strong></div><div><small>Total do período</small><strong><?= array_sum($values) ?></strong></div></div></section>
<div><section class="cms-card"><header class="cms-card-head"><div><h2>Visitantes online</h2><small>Atividade dos últimos 10 minutos.</small></div><b class="cms-count"><?= (int) $r['online_count'] ?></b></header><?php if ($r['online'] === []): ?><?= V::empty('Ninguém online agora.') ?><?php endif; foreach ($r['online'] as $o): ?><div class="cms-row"><code class="cms-chip"><?= V::e($o['path']) ?></code><small><?= V::e(date('H:i', strtotime($o['last_seen']))) ?></small></div><?php endforeach; ?></section>
<section class="cms-card"><header class="cms-card-head"><div><h2>Páginas mais vistas</h2></div></header><?php if ($r['top'] === []): ?><?= V::empty('Sem acessos no período.') ?><?php endif; foreach ($r['top'] as $t): ?><div class="cms-row"><code class="cms-chip"><?= V::e($t['path']) ?></code><strong><?= (int) $t['total'] ?></strong></div><?php endforeach; ?></section></div></div>
